function sumOfEncryptedInt(nums) {
  let total = 0;
  for (const x of nums) {
    let rest = x;
    let largest = 0;
    let ones = 0;
    while (rest > 0) {
      largest = Math.max(largest, rest % 10);
      ones = ones * 10 + 1;
      rest = Math.floor(rest / 10);
    }
    total += largest * ones;
  }
  return total;
}

