function sumOfEncryptedInt(nums) {
  let total = 0;
  for (const x of nums) {
    const digits = String(x).split('');
    const top = digits.reduce((a, b) => (b > a ? b : a));
    total += Number(digits.map(() => top).join(''));
  }
  return total;
}

