function generate(rand, size) {
  const n = size === 'large' ? 50 : 1 + Math.floor(rand() * 6);
  const nums = Array.from({ length: n }, () => {
    const digits = 1 + Math.floor(rand() * 3);
    const value = Math.floor(rand() * 10 ** digits);
    return rand() < 0.05 ? 1000 : Math.max(1, value);
  });
  return [nums];
}
